.stage {
      height: 28rem;
      border: 1px dashed var(--is-border);
      border-radius: var(--is-radius);
      background:
        radial-gradient(60rem 30rem at 50% 100%,
          color-mix(in srgb, var(--is-accent) 14%, transparent),
          transparent 60%);
      position: relative;
    }
    pre.log {
      font-family: ui-monospace, monospace; font-size: .8rem;
      background: var(--is-bg-elev); border: 1px solid var(--is-border);
      border-radius: var(--is-radius); padding: .55rem .75rem;
      max-height: 9rem; overflow: auto;
    }

